const DEFAULT={stage:'Configuration',mode:'validation',holidays:[],coverage:{},delegates:[],reminderDays:3,escalationDays:7,uat:{},reconciliation:null};
async function bounded(request,max){const reader=request.body?.getReader();if(!reader)throw fail('Missing request.');let length=0;const chunks=[];for(;;){const r=await reader.read();if(r.done)break;length+=r.value.byteLength;if(length>max){await reader.cancel();throw fail('Use a smaller file or import batch.',413);}chunks.push(r.value);}const bytes=new Uint8Array(length);let at=0;for(const chunk of chunks){bytes.set(chunk,at);at+=chunk.length;}return bytes;}
async function settings(db){const r=await q(db,"SELECT * FROM leave_settings WHERE id='main'").first();return {data:{...DEFAULT,...parse(r?.data_json)},version:r?.version||0};}
async function profiles(db,id){return Object.fromEntries((await rows(db,"SELECT section,data_json FROM employee_profile_sections WHERE employee_id=? AND section IN ('overview','employment','exit')",id)).map(r=>[r.section,parse(r.data_json)]));}
async function person(db,id,active=true){const e=await q(db,'SELECT employee_id,employee_name,email,department,position,active,updated_at FROM employees WHERE employee_id=?',id).first();if(!e||active&&!e.active)throw fail('A current employee record is required.',403);const p=await profiles(db,id);if(active&&(['Exited','Alumni','Resigned'].includes(p.overview?.employmentStatus)||p.exit?.autoLifecycle==='Enabled'&&p.exit.lastWorkingDay<today()))throw fail('This employee is no longer active.',403);return {...e,profile:p};}
async function assignment(db,id){const r=await q(db,'SELECT * FROM leave_assignments WHERE employee_id=?',id).first();return {data:parse(r?.data_json),version:r?.version||0};}
