function audit(db,user,action,id,detail){return q(db,'INSERT INTO audit_events (audit_id,occurred_at,actor_email,module_code,action,resource_type,resource_id,purpose,after_json) VALUES (?,?,?,?,?,?,?,?,?)',crypto.randomUUID(),stamp(),user.email,'leave',action,'leave',id,'leave_management',JSON.stringify(detail));}
function ledger(db,a,reference,action,d,user){return q(db,'INSERT INTO leave_ledger (id,account_id,reference,action,data_json,actor_email,created_at) VALUES (?,?,?,?,?,?,?)',crypto.randomUUID(),a.id,reference,action,JSON.stringify(d),user.email,stamp());}
function guard(db,table,id,version,data){const keys=Object.keys(data);return q(db,`UPDATE ${table} SET ${keys.map(k=>k+'=?').join(',')}${keys.length?',':''}version=CASE WHEN version=? THEN version+1 ELSE NULL END WHERE ${table==='leave_assignments'?'employee_id':'id'}=?`,...Object.values(data),version,id);}
function accountChange(db,a,delta,reference,action,user){const next={updated_at:stamp()};for(const k of ['allocated','accrued','carried','expired','adjustment','reserved','used','reserved_carry','used_carry','expired_carry'])if(delta[k]!==undefined)next[k]=a[k]+delta[k];return [guard(db,'leave_accounts',a.id,a.version,next),ledger(db,a,reference,action,delta,user)];}
async function token(request,raw,db,user){const key=request.headers.get('idempotency-key');if(!/^[a-zA-Z0-9_-]{16,100}$/.test(key||''))throw fail('Refresh and try again with a request reference.');const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(request.method+' '+new URL(request.url).pathname+' '+raw))),n=>n.toString(16).padStart(2,'0')).join(''),module='leave:'+user.userId,old=await q(db,'SELECT * FROM idempotency_keys WHERE module_code=? AND idempotency_key=?',module,key).first();if(old){if(old.request_hash!==hash)throw fail('That reference was used for a different action.',409);return {replay:json(parse(old.response_json),old.response_status)}}return {module,key,hash};}
