 const route=await routeFor(db,e,a.data,env),team=await teamAvailability(db,{role:'hr'},cal.start,cal.end,config,e.department);const coverageWarning=team.days.find(x=>x.available-1<(config.coverage[e.department]?.minimum||0));if(coverageWarning&&d.enforceCoverage===true&&d.coverageApproved===true)throw fail('This approved institutional policy requires P&C to resolve coverage before submission.',409);
